-- Comparative diagnostic, using the exact Git baseline generated by CI.
-- No Roblox engine latency, recipient fanout, or universal performance guarantee.
local currentPolicy, baselinePolicy, currentGate, baselineGate
if type(dofile)=="function" then
    currentPolicy=dofile("server/TextPolicy.lua")
    baselinePolicy=dofile("tests/.baseline/TextPolicy.lua")
    currentGate=dofile("server/DeliveryGate.lua")
    baselineGate=dofile("tests/.baseline/DeliveryGate.lua")
else
    currentPolicy=require("../server/TextPolicy")
    baselinePolicy=require("./.baseline/TextPolicy")
    currentGate=require("../server/DeliveryGate")
    baselineGate=require("./.baseline/DeliveryGate")
end

local function timing(run)
    local before=os.clock()
    local digest=run()
    return os.clock()-before,digest
end
local function compare(name, baseline, current, n)
    local bTimes,cTimes={},{}
    local digest
    for trial=1,3 do
        local bt,bd,ct,cd
        if trial%2==1 then
            bt,bd=timing(baseline)
            ct,cd=timing(current)
        else
            ct,cd=timing(current)
            bt,bd=timing(baseline)
        end
        assert(bd==cd and (digest==nil or digest==bd),"benchmark semantic mismatch: "..name)
        digest=bd
        bTimes[#bTimes+1]=bt
        cTimes[#cTimes+1]=ct
    end
    table.sort(bTimes)
    table.sort(cTimes)
    print(string.format("BENCH %s n=%d baseline_ms=%.3f current_ms=%.3f ratio=%.3f checksum=%d",name,n,bTimes[2]*1000,cTimes[2]*1000,bTimes[2]/math.max(cTimes[2],1e-9),digest))
end

local function syntheticWord(i, len)
    local chars={}
    for k=1,len do
        chars[k]=string.char(97+(i%26))
        i=math.floor(i/26)
    end
    return table.concat(chars)
end
local function policyRunner(policy, data, config, corpus, repetitions)
    local check=policy.new(config,data)
    return function()
        local digest=0
        for i=1,repetitions do
            for j,msg in ipairs(corpus) do
                local ok=check(msg)
                digest=(digest*31+(ok and 1 or 0)+j)%2147483647
            end
        end
        return digest
    end
end
local config={MaxMessageBytes=512,MaxTokens=80,MaxTokenBytes=64,EnableFuzzy=true}
local words,phrases={},{}
for i=1,256 do
    words[i]=syntheticWord(i,20)
    phrases[i]=syntheticWord(i,8).." "..syntheticWord(i+300,8)
end
local data={Words=words,Phrases=phrases,AllowWords={},BlockSymbols={}}
local corpus={
    string.rep("zbcdefghijklmnopqrst ",18),
    string.rep("qwertyuiopasdfghjklz ",18),
    words[11],
    "hello "..phrases[20].." there",
    words[5]:sub(1,19).."z",
    "hello team",
    "áéíóú vamos jogar",
    string.rep("hello ",40),
}
-- Baseline and current fuzzy semantics are equal for this ASCII dictionary (all length 20).
compare("lexical_256_rules_fuzzy",policyRunner(baselinePolicy,data,config,corpus,20),policyRunner(currentPolicy,data,config,corpus,20),#corpus*20)
config.EnableFuzzy=false
compare("lexical_256_rules_exact",policyRunner(baselinePolicy,data,config,corpus,100),policyRunner(currentPolicy,data,config,corpus,100),#corpus*100)

local gateConfig={MessagesPerSecond=20,DecisionTTL=10,MaxCachedMessages=256}
local function oldAllow() return true,"allow" end
local function gateRunner(old, mode, n)
    return function()
        local gate=(old and baselineGate or currentGate).new(gateConfig)
        local digest=0
        for i=1,n do
            local id,now
            if mode=="fanout" then
                local message=math.floor((i-1)/50)
                id=tostring(message)
                now=message*0.06
            elseif mode=="saturated" then
                id=tostring(i)
                now=i*0.005
            else
                id=tostring(i)
                now=i*0.06
            end
            local ok
            if old then ok=gate:Decide("sender",id,now,oldAllow)
            else ok=gate:Admit("sender",id,now,"channel") end
            digest=(digest*31+(ok and 1 or 0))%2147483647
        end
        return digest
    end
end
for _, mode in ipairs({"unique","saturated","fanout"}) do
    compare("admission_"..mode,gateRunner(true,mode,30000),gateRunner(false,mode,30000),30000)
end
print("PASS: benchmark decision checksums")
